parameters.script:
// ============ 股票条件提醒 ============
// 条件写在 WATCH 里，每只股票可以不一样；没写的走默认值。

var DEFAULT_UP = 3.0;      // 默认：涨幅 >= 3% 提醒
var DEFAULT_DOWN = -3.0;   // 默认：跌幅 <= -3% 提醒

// "any" = 任一条件命中就提醒；"all" = 配置的条件全部满足才提醒
var MODE = "any";

// 只在 A 股交易时段执行（周一~周五 09:30-11:30 / 13:00-15:00）
var ONLY_TRADING_HOURS = true;

// 条件字段：
//   up   涨幅 >= 该值(%)      down 跌幅 <= 该值(%)
//   high 价格 >= 该值          low  价格 <= 该值
//   vr   量比 >= 该值
// 不写 up/down 就用 DEFAULT_UP / DEFAULT_DOWN；写 null 表示这条不判断
var WATCH = [
    { code: "sh600000" },                                                  // 浦发银行：默认 ±3%
    { code: "sz000001", up: 5.0, down: -5.0 },                             // 平安银行：放宽到 ±5%
    { code: "sh000001", up: 1.5, down: -1.5 },                             // 上证指数：阈值收紧
    { code: "sz300750", up: null, down: null, high: 260, low: 240, vr: 2.0 } // 宁德时代：只看价格/量比
];

function fmtPct(v) { return (v >= 0 ? "+" : "") + v.toFixed(2) + "%"; }

var now = new Date();
var wd = now.getDay();
var hm = now.getHours() * 100 + now.getMinutes();
var inSession = (wd >= 1 && wd <= 5) &&
    ((hm >= 930 && hm <= 1130) || (hm >= 1300 && hm <= 1500));

var out = { ran: false, inSession: inSession, alerts: 0, alertText: "", summary: "", error: "" };

if (!ONLY_TRADING_HOURS || inSession) {
    try {
        var codes = [];
        var conf = {};
        for (var i = 0; i < WATCH.length; i++) {
            codes.push(WATCH[i].code);
            conf[WATCH[i].code.substring(2)] = WATCH[i];   // 用 6 位代码匹配
        }

        var resp = vflow.network.http_request({
            url: "https://qt.gtimg.cn/q=" + codes.join(","),
            method: "GET",
            timeout: 8
        });

        var rows = String(resp.response_body).split(";");
        var lines = [];
        var alerts = [];

        for (var i = 0; i < rows.length; i++) {
            var row = rows[i];
            if (!row || row.indexOf('="') < 0) continue;

            var f = row.substring(row.indexOf('="') + 2).split("~");
            if (f.length < 35) continue;

            var name  = f[1];
            var price = parseFloat(f[3]);    // 现价
            var chg   = parseFloat(f[32]);   // 涨跌幅 %
            var vr    = parseFloat(f[49]);   // 量比
            if (!price || isNaN(chg)) continue;   // 停牌/无数据

            var c = conf[f[2]] || {};
            // 未写该字段 = 用默认阈值；显式写 null = 这条不判断
            var up   = c.up   === undefined ? DEFAULT_UP   : c.up;
            var down = c.down === undefined ? DEFAULT_DOWN : c.down;

            // 逐条判断，命中的记进 hits
            var hits = [];
            if (up   != null && chg >= up)         hits.push("涨幅≥" + up + "%");
            if (down != null && chg <= down)       hits.push("跌幅≤" + down + "%");
            if (c.high != null && price >= c.high) hits.push("价格≥" + c.high);
            if (c.low  != null && price <= c.low)  hits.push("价格≤" + c.low);
            if (c.vr   != null && vr >= c.vr)      hits.push("量比≥" + c.vr);

            var total = (up != null ? 1 : 0) + (down != null ? 1 : 0) +
                        (c.high != null ? 1 : 0) + (c.low != null ? 1 : 0) +
                        (c.vr != null ? 1 : 0);
            var hit = MODE === "all" ? (hits.length > 0 && hits.length === total) : hits.length > 0;

            var rowText = name + " " + price + " " + fmtPct(chg);
            lines.push((hit ? "● " : "  ") + rowText + (hit ? "  [" + hits.join(" & ") + "]" : ""));
            if (hit) alerts.push(rowText + "  (" + hits.join(" & ") + ")");
        }

        out.ran = true;
        out.alerts = alerts.length;
        out.summary = lines.join("\n");
        out.alertText = alerts.join("\n");

        if (alerts.length > 0) {
            vflow.notification.send_notification({
                title: "股价提醒 " + alerts.length + " 只",
                message: alerts.join("\n")
            });
        }
    } catch (e) {
        out.error = String(e);
    }
}

out;
